using MessagePack;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class DuplicateKeyAndDepthReceiptTests
{
    [Fact]
    public void DepthStep_AtMaximumDepth_Throws()
    {
        MessagePackSecurity security = MessagePackSecurity.UntrustedData.WithMaximumObjectGraphDepth(3);
        var reader = new MessagePackReader(new ReadOnlyMemory<byte>(new byte[] { 0xc0 }));
        reader.Depth = 3;
        bool threw = false;
        try
        {
            security.DepthStep(ref reader);
        }
        catch (InsufficientExecutionStackException)
        {
            threw = true;
        }

        Assert.True(threw, "DepthStep must throw when the reader is already at MaximumObjectGraphDepth.");
    }

    [Fact]
    public async Task DuplicateIntKeys_AreReportedOrBothMembersSerialized()
    {
        string source = """
            using MessagePack;

            namespace Repro
            {
                [MessagePackObject]
                public class Dup
                {
                    [Key(0)]
                    public int FirstValue { get; set; }

                    [Key(0)]
                    public int SecondValue { get; set; }
                }

                [GeneratedMessagePackResolver]
                partial class MyResolver
                {
                }
            }
            """;

        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        IEnumerable<MetadataReference> refs = Enumerable.Concat<MetadataReference>(framework, ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReproAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out ImmutableArray<Diagnostic> generatorDiagnostics);
        GeneratorDriverRunResult run = driver.GetRunResult();
        string generated = string.Join("\n", run.GeneratedTrees.Select(t => t.ToString()));

        ImmutableArray<DiagnosticAnalyzer> analyzers = typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly.GetTypes()
            .Where(t => !t.IsAbstract && typeof(DiagnosticAnalyzer).IsAssignableFrom(t) && t.GetConstructor(Type.EmptyTypes) is not null)
            .Select(t => (DiagnosticAnalyzer)Activator.CreateInstance(t)!)
            .ToImmutableArray();
        ImmutableArray<Diagnostic> analyzerDiagnostics = await compilation.WithAnalyzers(analyzers).GetAnalyzerDiagnosticsAsync();

        bool msgPackError = generatorDiagnostics.Concat(run.Diagnostics).Concat(analyzerDiagnostics)
            .Any(d => d.Severity == DiagnosticSeverity.Error && d.Id.StartsWith("MsgPack", StringComparison.Ordinal));
        bool bothMembersGenerated = generated.Contains("FirstValue") && generated.Contains("SecondValue");

        Assert.True(
            msgPackError || bothMembersGenerated,
            "Duplicate [Key(0)] members must either be reported as a MsgPack error or both be serialized; instead SecondValue was silently dropped. Generated:\n" + generated);
    }
}
